INSERT INTO `books` (`id`,`category_id`,`title`,`author`,`publisher`,`price`,`original_price`,`stock`,`cover`,`intro`,`tags`,`status`) VALUES
(1,1,'活着','余华','作家出版社',29.00,39.00,24,'','地主少爷福贵一生的起落，从败光家产到孤身一人。余华用最干净的语言写尽苦难，却让「活着」本身成为一种力量。','经典,当代文学','on'),
(2,1,'平凡的世界','路遥','北京十月文艺出版社',79.00,98.00,10,'','以孙少安、孙少平兄弟为主线，写黄土高原上普通人的奋斗与尊严。篇幅较长，建议分三册慢慢读。','茅盾文学奖,成长','on'),
(3,1,'百年孤独','加西亚·马尔克斯','南海出版公司',55.00,68.00,10,'','布恩迪亚家族七代人的兴衰，魔幻现实主义的代表作。人名容易绕晕，建议边读边画家族图谱。','经典,拉美文学','on'),
(4,1,'解忧杂货店','东野圭吾','南海出版公司',39.50,49.50,9,'','五个故事通过一间杂货店的投信口串起来。结构精巧，情绪收得很稳，适合当睡前读物。','日系,温情','on'),
(5,1,'人间失格','太宰治','作家出版社',32.00,42.00,13,'','一个把自己活成笑话的人的自白。读的时候会不舒服，但那种不舒服是准确的。','日系,经典','on'),
(6,1,'围城','钱钟书','人民文学出版社',36.00,45.00,6,'','婚姻是座围城，城外的人想进去，城里的人想出来。比喻密度高，读着读着会笑出声。','讽刺,现代文学','on'),
(7,1,'边城','沈从文','人民文学出版社',26.00,35.00,11,'','茶峒的河、渡船和翠翠。文字干净得像水，结局却让人闷很久。','乡土,经典','on'),
(8,1,'月亮与六便士','毛姆','上海译文出版社',34.00,46.00,21,'','一个人抛下一切去画画。你可以说他勇敢，也可以说他自私，毛姆不替你选。','英国文学,理想','on'),
(9,1,'长夜','周一·禾','人民文学出版社',127.10,158.90,13,'','《长夜》把日常写得很慢：人物不急着解释自己，情绪都藏在细节里。适合睡前读两章。','小说,当代文学','on'),
